private fun transformBarcodeScannerResultToViewCoordinates(barcode: BarCodeScannerResult) {
  val cornerPoints = barcode.cornerPoints
  val previewWidth = previewView.width.toFloat()
  val previewHeight = previewView.height.toFloat()
  val imageWidth = barcode.width.toFloat()
  val imageHeight = barcode.height.toFloat()

  if (previewWidth <= 0 || previewHeight <= 0 || imageWidth <= 0 || imageHeight <= 0) {
    return
  }

  val scaleX: Float
  val scaleY: Float

  when (previewView.scaleType) {
    PreviewView.ScaleType.FIT_CENTER -> {
      val previewAspectRatio = previewWidth / previewHeight
      val imageAspectRatio = imageWidth / imageHeight

      if (previewAspectRatio > imageAspectRatio) {
        scaleY = previewHeight / imageHeight
        scaleX = scaleY
      } else {
        // Preview is taller - letterbox on top/bottom
        scaleX = previewWidth / imageWidth
        scaleY = scaleX
      }
    }
    PreviewView.ScaleType.FILL_CENTER -> {
      val previewAspectRatio = previewWidth / previewHeight
      val imageAspectRatio = imageWidth / imageHeight

      if (previewAspectRatio > imageAspectRatio) {
        // Preview is wider - scale to fill width, crop top/bottom
        scaleX = previewWidth / imageWidth
        scaleY = scaleX
      } else {
        // Preview is taller - scale to fill height, crop left/right
        scaleY = previewHeight / imageHeight
        scaleX = scaleY
      }
    }
    else -> {
      scaleX = previewWidth / imageWidth
      scaleY = previewHeight / imageHeight
    }
  }

  cornerPoints.mapX { index ->
    val originalX = cornerPoints[index]
    (originalX * scaleX).roundToInt()
  }

  cornerPoints.mapY { index ->
    val originalY = cornerPoints[index]
    (originalY * scaleY).roundToInt()
  }

  barcode.cornerPoints = cornerPoints
  barcode.height = previewHeight.toInt()
  barcode.width = previewWidth.toInt()
}

private fun getCornerPointsAndBoundingBox(
  cornerPoints: List<Int>,
  boundingBox: BoundingBox
): Pair<ArrayList<Bundle>, Bundle> {
  val density = previewView.resources.displayMetrics.density
  val convertedCornerPoints = ArrayList<Bundle>()
  for (i in cornerPoints.indices step 2) {
    val y = cornerPoints[i].toFloat() / density
    val x = cornerPoints[i + 1].toFloat() / density
    convertedCornerPoints.add(
      Bundle().apply {
        putFloat("x", x)
        putFloat("y", y)
      }
    )
  }
  val boundingBoxBundle = Bundle().apply {
    putParcelable(
      "origin",
      Bundle().apply {
        putFloat("x", boundingBox.x.toFloat() / density)
        putFloat("y", boundingBox.y.toFloat() / density)
      }
    )
    putParcelable(
      "size",
      Bundle().apply {
        putFloat("width", boundingBox.width.toFloat() / density)
        putFloat("height", boundingBox.height.toFloat() / density)
      }
    )
  }
  return convertedCornerPoints to boundingBoxBundle
}

private fun onBarcodeScanned(barcode: BarCodeScannerResult) {
  if (shouldScanBarcodes) {
    transformBarcodeScannerResultToViewCoordinates(barcode)
    val (cornerPoints, boundingBox) = getCornerPointsAndBoundingBox(
      barcode.cornerPoints,
      barcode.boundingBox
    )
    onBarcodeScanned(
      BarcodeScannedEvent(
        target = id,
        data = barcode.value.toString(),
        raw = barcode.raw.toString(),
        type = BarcodeType.mapFormatToString(barcode.type),
        cornerPoints = cornerPoints,
        bounds = boundingBox,
        extra = barcode.extra
      )
    )
  }
}

import android.content.Context
import android.content.pm.PackageManager

object CameraUtils {
  private const val GOOGLE_PLAY_STORE_PACKAGE = "com.android.vending"

  fun hasGooglePlayServices(context: Context?): Boolean {
    if (context == null) {
      return false
    }
    return try {
      context.packageManager
        .getPackageInfo(GOOGLE_PLAY_STORE_PACKAGE, 0)
      true
    } catch (_: PackageManager.NameNotFoundException) {
      false
    }
  }

  fun isMLKitBarcodeScannerAvailable(): Boolean {
    return try {
      Class.forName("com.google.mlkit.vision.barcode.BarcodeScanning")
      true
    } catch (_: ClassNotFoundException) {
      false
    }
  }

  fun isMLKitAvailable(context: Context?): Boolean {
    if (!hasGooglePlayServices(context)) {
      return false
    }

    return isMLKitBarcodeScannerAvailable()
  }
}

@OptIn(ExperimentalGetImage::class)
class BarcodeAnalyzer(private val lensFacing: CameraType, formats: List<BarcodeType>, val onComplete: (BarCodeScannerResult) -> Unit) : ImageAnalysis.Analyzer {
  private val barcodeFormats = if (formats.isEmpty()) {
    0
  } else {
    formats.map { it.mapToBarcode() }.reduce { acc, it ->
      acc or it
    }
  }
  private var barcodeScannerOptions =
    BarcodeScannerOptions.Builder()
      .setBarcodeFormats(barcodeFormats)
      .build()
  private var barcodeScanner = BarcodeScanning.getClient(barcodeScannerOptions)

  override fun analyze(imageProxy: ImageProxy) {
    val mediaImage = imageProxy.image

    if (mediaImage != null) {
      val rotation = CameraViewHelper.getCorrectCameraRotation(imageProxy.imageInfo.rotationDegrees, lensFacing)
      val image = InputImage.fromMediaImage(mediaImage, rotation)

      barcodeScanner.process(image)
        .addOnSuccessListener { barcodes ->
          if (barcodes.isEmpty()) {
            return@addOnSuccessListener
          }
          val barcode = barcodes.first()
          val raw = barcode.rawValue ?: barcode.rawBytes?.let { String(it) }

          val cornerPoints = barcode.cornerPoints?.let { points ->
            // Pre-allocate array
            IntArray(points.size * 2).apply {
              points.forEachIndexed { index, point ->
                this[index * 2] = point.x
                this[index * 2 + 1] = point.y
              }
            }.toMutableList()
          } ?: mutableListOf()

          val extra = BarCodeScannerResultSerializer.parseExtraDate(barcode)
          onComplete(
            BarCodeScannerResult(
              barcode.format,
              barcode.displayValue,
              raw,
              extra,
              cornerPoints,
              imageProxy.width,
              imageProxy.height
            )
          )
        }
        .addOnFailureListener {
          Log.d("SCANNER", it.cause?.message ?: "Barcode scanning failed")
        }
        .addOnCompleteListener {
          imageProxy.close()
        }
    }
  }
}

import android.graphics.Bitmap
import android.util.Log
import com.google.android.gms.tasks.Task
import com.google.mlkit.vision.barcode.BarcodeScannerOptions
import com.google.mlkit.vision.barcode.BarcodeScanning
import com.google.mlkit.vision.barcode.common.Barcode
import com.google.mlkit.vision.common.InputImage
import expo.modules.camera.utils.BarCodeScannerResult
import kotlinx.coroutines.Dispatchers
import kotlinx.coroutines.suspendCancellableCoroutine
import kotlinx.coroutines.withContext
import kotlin.coroutines.resume
import kotlin.coroutines.resumeWithException

class MLKitBarCodeScanner {
  private var barCodeTypes: List<Int>? = null
  private var barcodeScannerOptions =
    BarcodeScannerOptions.Builder()
      .setBarcodeFormats(Barcode.FORMAT_ALL_FORMATS)
      .build()
  private var barcodeScanner = BarcodeScanning.getClient(barcodeScannerOptions)

  suspend fun scan(bitmap: Bitmap): List<BarCodeScannerResult> = withContext(Dispatchers.IO) {
    val inputImage = InputImage.fromBitmap(bitmap, 0)
    try {
      val result: List<Barcode> = barcodeScanner.process(inputImage).await()
      val results = mutableListOf<BarCodeScannerResult>()
      if (result.isEmpty()) {
        return@withContext results
      }
      for (barcode in result) {
        results.add(BarCodeScannerResultSerializer.parseBarcodeScanningResult(barcode, inputImage))
      }
      return@withContext results
    } catch (e: Exception) {
      Log.e(TAG, "Failed to detect barcode: " + e.message)
      return@withContext emptyList()
    }
  }

  fun setSettings(formats: List<Int>) {
    if (areNewAndOldBarCodeTypesEqual(formats)) {
      return
    }
    val barcodeFormats = formats.reduce { acc, it ->
      acc or it
    }

    barCodeTypes = formats
    barcodeScannerOptions = BarcodeScannerOptions.Builder()
      .setBarcodeFormats(barcodeFormats)
      .build()
    barcodeScanner = BarcodeScanning.getClient(barcodeScannerOptions)
  }

  private fun areNewAndOldBarCodeTypesEqual(newBarCodeTypes: List<Int>): Boolean {
    barCodeTypes?.run {
      // create distinct-values sets
      val prevTypesSet = toHashSet()
      val nextTypesSet = newBarCodeTypes.toHashSet()

      // sets sizes are equal -> possible content equality
      if (prevTypesSet.size == nextTypesSet.size) {
        prevTypesSet.removeAll(nextTypesSet)
        // every element from new set was in previous one -> sets are equal
        return prevTypesSet.isEmpty()
      }
    }
    return false
  }

  companion object {
    private val TAG = MLKitBarCodeScanner::class.java.simpleName
  }
}

suspend fun <T> Task<T>.await(): T = suspendCancellableCoroutine { continuation ->
  addOnSuccessListener { result ->
    continuation.resume(result)
  }
  addOnFailureListener { exception ->
    continuation.resumeWithException(exception)
  }
  addOnCanceledListener {
    continuation.cancel()
  }
}

import android.os.Bundle
import android.util.Pair
import com.google.mlkit.vision.barcode.common.Barcode
import com.google.mlkit.vision.common.InputImage
import expo.modules.camera.utils.BarCodeScannerResult

object BarCodeScannerResultSerializer {
  fun toBundle(result: BarCodeScannerResult, density: Float) =
    Bundle().apply {
      putString("data", result.value)
      putString("raw", result.raw)
      putInt("type", result.type)
      putBundle("extra", result.extra)
      val cornerPointsAndBoundingBox = getCornerPointsAndBoundingBox(result.cornerPoints, result.boundingBox, density)
      putParcelableArrayList("cornerPoints", cornerPointsAndBoundingBox.first)
      putBundle("bounds", cornerPointsAndBoundingBox.second)
    }

  fun parseBarcodeScanningResult(barcode: Barcode, inputImage: InputImage? = null): BarCodeScannerResult {
    val raw = barcode.rawValue ?: barcode.rawBytes?.let { String(it) }
    val value = if (barcode.valueType == Barcode.TYPE_CONTACT_INFO) {
      raw
    } else {
      barcode.displayValue
    }
    val cornerPoints = mutableListOf<Int>()
    barcode.cornerPoints?.let { points ->
      for (point in points) {
        cornerPoints.addAll(listOf(point.x, point.y))
      }
    }

    val extra = parseExtraDate(barcode)
    return BarCodeScannerResult(barcode.format, value, raw, extra, cornerPoints, inputImage?.height ?: 0, inputImage?.width ?: 0)
  }

  private fun getCornerPointsAndBoundingBox(
    cornerPoints: List<Int>,
    boundingBox: BarCodeScannerResult.BoundingBox,
    density: Float
  ): Pair<ArrayList<Bundle>, Bundle> {
    val convertedCornerPoints = ArrayList<Bundle>()
    for (i in cornerPoints.indices step 2) {
      val x = cornerPoints[i].toFloat() / density
      val y = cornerPoints[i + 1].toFloat() / density

      convertedCornerPoints.add(getPoint(x, y))
    }
    val boundingBoxBundle = Bundle().apply {
      putParcelable("origin", getPoint(boundingBox.x.toFloat() / density, boundingBox.y.toFloat() / density))
      putParcelable("size", getSize(boundingBox.width.toFloat() / density, boundingBox.height.toFloat() / density))
    }
    return Pair(convertedCornerPoints, boundingBoxBundle)
  }

  fun parseExtraDate(barcode: Barcode): Bundle {
    val result = Bundle()

    when (barcode.valueType) {
      Barcode.TYPE_CONTACT_INFO -> {
        val info = barcode.contactInfo
        result.apply {
          putString("type", "contactInfo")
          putString("firstName", info?.name?.first)
          putString("middleName", info?.name?.middle)
          putString("lastName", info?.name?.last)
          putString("title", info?.title)
          putString("organization", info?.organization)
          putString("email", info?.emails?.firstOrNull()?.address)
          putString("phone", info?.phones?.firstOrNull()?.number)
          putString("url", info?.urls?.firstOrNull())
          putString("address", info?.addresses?.firstOrNull()?.addressLines?.firstOrNull())
        }
      }

      Barcode.TYPE_GEO -> {
        val geo = barcode.geoPoint
        result.apply {
          putString("type", "geoPoint")
          putString("lat", geo?.lat.toString())
          putString("lng", geo?.lng.toString())
        }
      }

      Barcode.TYPE_SMS -> {
        val sms = barcode.sms
        result.apply {
          putString("type", "sms")
          putString("phoneNumber", sms?.phoneNumber)
          putString("message", sms?.message)
        }
      }

      Barcode.TYPE_URL -> {
        val url = barcode.url
        result.putString("type", "url")
        result.putString("url", url?.url)
      }

      Barcode.TYPE_CALENDAR_EVENT -> {
        val event = barcode.calendarEvent
        result.apply {
          result.putString("type", "calendarEvent")
          putString("summary", event?.summary)
          putString("description", event?.description)
          putString("location", event?.location)
          putString("start", event?.start?.toString())
          putString("end", event?.end?.toString())
        }
      }

      Barcode.TYPE_DRIVER_LICENSE -> {
        val license = barcode.driverLicense
        result.apply {
          result.putString("type", "driverLicense")
          putString("firstName", license?.firstName)
          putString("middleName", license?.middleName)
          putString("lastName", license?.lastName)
          putString("licenseNumber", license?.licenseNumber)
          putString("expiryDate", license?.expiryDate)
          putString("issueDate", license?.issueDate)
          putString("addressStreet", license?.addressStreet)
          putString("addressCity", license?.addressCity)
          putString("addressState", license?.addressState)
        }
      }

      Barcode.TYPE_EMAIL -> {
        val email = barcode.email
        result.apply {
          result.putString("type", "email")
          putString("address", email?.address)
          putString("subject", email?.subject)
          putString("body", email?.body)
        }
      }

      Barcode.TYPE_PHONE -> {
        val phone = barcode.phone
        result.apply {
          result.putString("type", "phone")
          putString("number", phone?.number)
          putString("phoneNumberType", phone?.type.toString())
        }
      }

      Barcode.TYPE_WIFI -> {
        val wifi = barcode.wifi
        result.apply {
          result.putString("type", "wifi")
          putString("ssid", wifi?.ssid)
          putString("password", wifi?.password)
          putString("type", wifi?.encryptionType.toString())
        }
      }
    }

    return result
  }

  private fun getSize(width: Float, height: Float) =
    Bundle().apply {
      putFloat("width", width)
      putFloat("height", height)
    }

  private fun getPoint(x: Float, y: Float) =
    Bundle().apply {
      putFloat("x", x)
      putFloat("y", y)
    }
}

